from django.db import migrations, models


def calcular_kwp(apps, schema_editor):
    """kWp das propostas existentes, pelos módulos do kit gravado."""
    Proposta = apps.get_model("propostas", "Proposta")
    for proposta in Proposta.objects.all():
        watts = sum(i.quantidade * (i.potencia_w or 0) for i in proposta.itens_kit.filter(tipo="modulo"))
        if watts:
            proposta.kwp = Decimal(watts) / 1000
            proposta.save(update_fields=["kwp"])


